// Parse: !task <name> | due:YYYY-MM-DD | <notes>
const raw = ($json.body?.content ?? $json.content ?? '').trim();
const text = raw.replace(/^!task\s*/i, '');
const parts = text.split('|').map(s => s.trim());
const name = parts[0] || '';
let due = '', notes = '';
for (const p of parts.slice(1)) {
  const m = p.match(/^due:\s*(\d{4}-\d{2}-\d{2})$/i);
  if (m) due = m[1]; else notes += (notes ? ' ' : '') + p;
}
const author = $json.body?.author?.username ?? 'unknown';
return { json: { name, due, notes, author } };
